// One-shot drift-close script for INTEL-OLLAMA-OBSIDIAN-MS0/MS1
// Generated by claude-a2b1b5ca on 2026-05-15 for post-compact /goal scope expansion.
// Idempotent: only flips status=unset units that have git evidence; leaves complete units untouched.
import fs from "node:fs";
import { execFileSync } from "node:child_process";

const NOW = new Date().toISOString();
const CHAT = "claude-a2b1b5ca";
const GIT_EXE = process.env.GIT_EXE || "C:\\Program Files\\Git\\bin\\git.exe";

function getCommits(unitId) {
  try {
    const r = execFileSync(GIT_EXE, ["-C", "H:/prism", "log", "--grep=" + unitId, "--pretty=%h", "-n", "10"], { encoding: "utf8" });
    return r.trim().split("\n").filter(Boolean);
  } catch (e) { return []; }
}

function processMilestone(path) {
  const j = JSON.parse(fs.readFileSync(path, "utf8"));
  let flippedThisRun = 0;
  let alreadyComplete = 0;
  let trulyMissing = 0;
  const trulyMissingList = [];

  for (const p of j.phases || []) {
    for (const u of p.units || []) {
      const wasComplete = u.status === "complete" || u.status === "completed";
      if (wasComplete) { alreadyComplete++; continue; }
      const commits = getCommits(u.id);
      if (commits.length > 0) {
        u.status = "complete";
        u.closed_at = NOW;
        u.closed_by = CHAT + " (post-compact drift-close)";
        u.close_evidence = {
          method: "git-log-grep",
          commits: commits.slice(0, 3),
          commit_count: commits.length,
          audit_unit_id: u.id
        };
        flippedThisRun++;
      } else {
        trulyMissing++;
        trulyMissingList.push(`${p.id}/${u.id} — ${(u.title || "").slice(0, 70)}`);
      }
    }
  }

  const totalUnits = (j.phases || []).reduce((acc, p) => acc + (p.units || []).length, 0);
  const completedUnits = alreadyComplete + flippedThisRun;
  j.completed_units = completedUnits;
  j.total_units = totalUnits;
  j.updated_at = NOW;

  if (completedUnits === totalUnits) {
    j.status = "complete";
    j.completed_at = NOW;
    j.completed_by = CHAT;
    j.completion_method = "post-compact drift audit (git log --grep per unit)";
  } else {
    j.status = "in_progress";
    j.in_progress_since = j.in_progress_since || NOW;
    j.drift_close_audit = {
      audited_at: NOW,
      audited_by: CHAT,
      method: "git log --grep=<unit_id> per atomic unit",
      flipped_this_run: flippedThisRun,
      already_complete_in_envelope: alreadyComplete,
      truly_missing_no_commits: trulyMissing,
      remaining_units: trulyMissingList,
      note: "Envelope previously claimed status=not_started while git showed " + completedUnits + "/" + totalUnits + " units shipped. This is an envelope-reality drift correction, not new work. Remaining " + trulyMissing + " units have no git evidence and represent real outstanding scope."
    };
  }

  fs.writeFileSync(path, JSON.stringify(j, null, 2) + "\n");
  return {
    id: j.id,
    total: totalUnits,
    alreadyComplete,
    flippedThisRun,
    trulyMissing,
    finalStatus: j.status,
    completedUnits
  };
}

const result0 = processMilestone("H:/prism/mcp-server/data/milestones/INTEL-OLLAMA-OBSIDIAN-MS0.json");
const result1 = processMilestone("H:/prism/mcp-server/data/milestones/INTEL-OLLAMA-OBSIDIAN-MS1.json");
console.log(JSON.stringify({ MS0: result0, MS1: result1 }, null, 2));
